 const reachable=new Set();let changed=true;while(changed){changed=false;for(const o of regular)if(!reachable.has(o.id)&&rects(o).some(r=>routes.some(a=>rects(a).some(b=>touching(r,b))))){reachable.add(o.id);changed=true;}}
